CFE_Status_t SAMPLE_APP_SendHkCmd(const SAMPLE_APP_SendHkCmd_t *Msg)
{
    int i;

    /*
    ** Get command execution counters...
    */
    SAMPLE_APP_Data.HkTlm.Payload.CommandErrorCounter = SAMPLE_APP_Data.CommandErrorCounter;
    SAMPLE_APP_Data.HkTlm.Payload.CommandCounter      = SAMPLE_APP_Data.CommandCounter;

    /*
    ** Send housekeeping telemetry packet...
    */
    CFE_SB_TimeStampMsg(CFE_MSG_PTR(SAMPLE_APP_Data.HkTlm.TelemetryHeader));
    CFE_SB_TransmitMsg(CFE_MSG_PTR(SAMPLE_APP_Data.HkTlm.TelemetryHeader), true);

    /*
    ** Manage any pending table loads, validations, etc.
    */
    for (i = 0; i < SAMPLE_APP_PLATFORM_NUMBER_OF_TABLES; i++)
    {
        CFE_TBL_Manage(SAMPLE_APP_Data.TblHandles[i]);
    }

    return CFE_SUCCESS;
}

/*************************************************************************/
/*
** Type definition (Sample App housekeeping)
*/

typedef struct SAMPLE_APP_HkTlm_Payload
{
    uint8 CommandCounter;
    uint8 CommandErrorCounter;
} SAMPLE_APP_HkTlm_Payload_t;

static CFE_SB_MsgId_t CMD_MID     = CFE_SB_MSGID_RESERVED;
static CFE_SB_MsgId_t SEND_HK_MID = CFE_SB_MSGID_RESERVED;

CFE_SB_MsgId_t MsgId = CFE_SB_INVALID_MSG_ID;

/* cache the local MID Values here, this avoids repeat lookups */
if (!CFE_SB_IsValidMsgId(CMD_MID))
{
    CMD_MID     = CFE_SB_ValueToMsgId(SAMPLE_APP_CMD_MID);
    SEND_HK_MID = CFE_SB_ValueToMsgId(SAMPLE_APP_SEND_HK_MID);
}

CFE_MSG_GetMsgId(&SBBufPtr->Msg, &MsgId);

/* Process all SB messages */
if (CFE_SB_MsgId_Equal(MsgId, SEND_HK_MID))
{
    /* Housekeeping request */
    SAMPLE_APP_SendHkCmd((const SAMPLE_APP_SendHkCmd_t *)SBBufPtr);
}
else if (CFE_SB_MsgId_Equal(MsgId, CMD_MID))
{
    /* Ground command */
    SAMPLE_APP_ProcessGroundCommand(SBBufPtr);

     ** Initialize housekeeping packet (clear user data area).
     */
    CFE_MSG_Init(CFE_MSG_PTR(SAMPLE_APP_Data.HkTlm.TelemetryHeader),
                 CFE_SB_ValueToMsgId(SAMPLE_APP_HK_TLM_MID),
                 sizeof(SAMPLE_APP_Data.HkTlm));

    /*
     ** Create Software Bus message pipe.
     */
    status = CFE_SB_CreatePipe(&SAMPLE_APP_Data.CommandPipe,
                               SAMPLE_APP_PLATFORM_PIPE_DEPTH,
                               SAMPLE_APP_PLATFORM_PIPE_NAME);
    if (status != CFE_SUCCESS)
    {
        CFE_EVS_SendEvent(SAMPLE_APP_CR_PIPE_ERR_EID,
                          CFE_EVS_EventType_ERROR,
                          "Sample App: Error creating SB Command Pipe, RC = 0x%08lX",
                          (unsigned long)status);
    }
}

if (status == CFE_SUCCESS)
{
    /*
    ** Subscribe to Housekeeping request commands
    */
    status = CFE_SB_Subscribe(CFE_SB_ValueToMsgId(SAMPLE_APP_SEND_HK_MID), SAMPLE_APP_Data.CommandPipe);
    if (status != CFE_SUCCESS)
    {
        CFE_EVS_SendEvent(SAMPLE_APP_SUB_HK_ERR_EID,
                          CFE_EVS_EventType_ERROR,
                          "Sample App: Error Subscribing to HK request, RC = 0x%08lX",
                          (unsigned long)status);
    }
}

if (status == CFE_SUCCESS)
{
    /*
    ** Subscribe to ground command packets
    */
    status = CFE_SB_Subscribe(CFE_SB_ValueToMsgId(SAMPLE_APP_CMD_MID), SAMPLE_APP_Data.CommandPipe);
    if (status != CFE_SUCCESS)
    {
        CFE_EVS_SendEvent(SAMPLE_APP_SUB_CMD_ERR_EID,
                          CFE_EVS_EventType_ERROR,
                          "Sample App: Error Subscribing to Commands, RC = 0x%08lX",
                          (unsigned long)status);

**          TEST CASE FUNCTIONS
**********************************************************************************
*/

void Test_SAMPLE_APP_ReportHousekeeping(void)
{
    /*
     * Test Case For:
     * void SAMPLE_APP_ReportHousekeeping( const CFE_SB_CmdHdr_t *Msg )
     */
    CFE_MSG_Message_t *MsgSend;
    CFE_MSG_Message_t *MsgTimestamp;

    /* Set up to capture send message address */
    UT_SetDataBuffer(UT_KEY(CFE_SB_TransmitMsg), &MsgSend, sizeof(MsgSend), false);

    /* Set up to capture timestamp message address */
    UT_SetDataBuffer(UT_KEY(CFE_SB_TimeStampMsg), &MsgTimestamp, sizeof(MsgTimestamp), false);

    /* Call unit under test, NULL pointer confirms command access is through APIs */
    SAMPLE_APP_SendHkCmd(NULL);

    /* Confirm message sent*/
    UtAssert_STUB_COUNT(CFE_SB_TransmitMsg, 1);
    UtAssert_ADDRESS_EQ(MsgSend, &SAMPLE_APP_Data.HkTlm);

    /* Confirm timestamp msg address */
    UtAssert_STUB_COUNT(CFE_SB_TimeStampMsg, 1);
    UtAssert_ADDRESS_EQ(MsgTimestamp, &SAMPLE_APP_Data.HkTlm);

    /*
     * Confirm that the CFE_TBL_Manage() call was done
     */
    UtAssert_STUB_COUNT(CFE_TBL_Manage, 1);
}

